from pathlib import Path
import pandas as pd,numpy as np,json,hashlib,html
R=Path.cwd();O=R/'reports/compatibility_null_validation/calibrator_extension'
A=pd.read_csv(O/'A_all_scores.csv');B=pd.read_csv(O/'B_consistency.csv');C=pd.read_csv(O/'C_dose_response.csv');D=pd.read_csv(O/'D_mechanism.csv');E=pd.read_csv(O/'E_associations.csv');roster=json.loads((O/'roster.json').read_text());checks=json.loads((O/'checks.json').read_text());prov=json.loads((O/'provenance.json').read_text())
# Presentation-only metadata: counts of fitting engines under each recorded design.
for df in [A,B,C,D,E]:
 df['fitting_engines_per_fit']=[({'FD001':80,'FD002':208,'FD003':80,'FD004':199}[s] if f=='original' else {'FD001':60,'FD002':156,'FD003':60,'FD004':149}.get(s,'see roster')) for s,f in zip(df.subset,df.family)]
for filename,df in [('A_all_scores.csv',A),('B_consistency.csv',B),('C_dose_response.csv',C),('D_mechanism.csv',D),('E_associations.csv',E)]:df.to_csv(O/filename,index=False)
summary=[]
for metric in ['Brier','NLL']:
 x=B[B.measure==metric];summary.append(dict(exploratory=True,metric=metric,groups=len(x),distinct_test_engines=707,helps=int((x.classification=='helps').sum()),hurts=int((x.classification=='hurts').sum()),unresolved=int((x.classification=='unresolved').sum()),negative_point=int((x.difference_vs_raw<0).sum()),positive_point=int((x.difference_vs_raw>0).sum())))
pd.DataFrame(summary).to_csv(O/'B_counts.csv',index=False)
counts=pd.DataFrame([dict(exploratory=True,subset=g['subset'],family=g['family'],architecture=g['arm'],test_engines=g['test_engines'],fixed_fits=len(g['fits']),calibration_engines_per_fit=','.join(str(f['calibration_engines']) for f in g['fits']),distinct_calibration_engines=len(set(e for f in g['fits'] for e in f['calibration_ids']))) for g in roster]);counts.to_csv(O/'engine_counts.csv',index=False)
fmt=lambda x:f'{x:.6g}'
pooled=A[A.subset=='pooled'];lines=['# Exploratory calibration and projection extension','',f"Protocol SHA256: `{checks['protocol']['protocol_sha256']}`. Locked before new calculations. No outcome, threshold, subgroup or decision criterion changed. One label-type implementation correction is documented separately.",'','Every analysis and estimate in this report is exploratory. Independent human review is still missing. No training, checkpoint loading or forward inference ran. All 588 input files were hashed before numerical analysis and remained unchanged. The original eight groups’ 64 raw/projected score estimates reproduce the preceding analysis to 1e-12.','', '44 groups, 220 fixed fits, 707 distinct official-test engines. Test counts by subset: FD001 100, FD002 259, FD003 100, FD004 248. Repeated fits and architectures never multiply these engine counts. Calibration partitions and IDs are listed per fit in roster.json; original hybrid runs retain their own partitions. The extra scope includes four GPU-repeat architectures and the two additional CV-selected LSTM/hybrid controls, five fits per subset/architecture. No saved prediction pair was missing.','', 'All score intervals and paired differences are 95% percentile CIs from 2000 synchronized engine-cluster bootstrap draws. Calibration maps are held fixed during the test bootstrap, so uncertainty from estimating calibration maps is excluded. Distinct engines receive equal pooled weight; within each engine, groups/fits receive equal weight. ECE pools group scores with engine-count weights across subsets; it is not ECE of averaged predictions. ECE5 uses fixed method/fit-specific quintile cuts; ECE10 uses fixed equal-width bins.','', '## A. Projection and calibrator comparison','', 'All 14 probability paths are reported for every group and pooled in A_all_scores.csv (2520 rows). Each row includes score CI, paired method-minus-raw CI, test count, fit count, and calibration counts. Negative paired differences favor the method. TrainOff is the fixed recorded training-weight offset; its parameters are not estimated on calibration labels. All other maps are fitted separately on each fit’s calibration engines. No calibration optimization failed.','']
for _,v in pooled[pooled.measure.isin(['Brier','NLL'])].iterrows():lines.append(f"- Exploratory {v['method']} {v['measure']} (707 engines): {fmt(v.estimate)}; difference vs raw {fmt(v.difference_vs_raw)} [{fmt(v.difference_ci_low)}, {fmt(v.difference_ci_high)}].")
lines+=['','Projection lowers pooled Brier/NLL; TrainOff alone has lower pooled scores than projection alone. This descriptive comparison does not provide a paired CI for TrainOff versus projection. Temperature, Platt, Isotonic and Beta have adverse pooled NLL results; Isotonic followed by projection also has a positive NLL difference CI versus raw. There is no universally favored processing path.','', '## B. Consistency','']
for x in summary:lines.append(f"- Exploratory {x['metric']} (44 groups; 707 distinct engines): helps {x['helps']}, hurts {x['hurts']}, unresolved {x['unresolved']}; {x['negative_point']} negative and {x['positive_point']} positive point differences.")
lines+=['','B_consistency.csv contains the sign and CI for every group, including all unfavorable point estimates. Helps requires CI upper endpoint <0; hurts requires lower endpoint >0. All other results are unresolved.','', '## C. Distance dose response','', 'C_dose_response.csv reports all four prespecified bins for all 44 groups (176 rows), with distinct engine counts, engine-fit row counts, Brier improvement and CI. Bins classify engine-fit pairs; an engine can appear in different bins across fits, so bin distinct-engine counts must not be summed. Positive improvement favors projection. The d=0 bin has zero improvement by construction. These are descriptive associations; projection magnitude and potential Brier change are mechanically related.','', '## D. Mechanism','']
for measure in ['above_U','below_L','signed_probability_change','gap_change']:
 x=D[D.measure==measure];lines.append(f"- Exploratory {measure}: group range {fmt(x.estimate.min())} to {fmt(x.estimate.max())}; 44 groups and 707 distinct test engines, group-specific counts/CIs in D_mechanism.csv.")
x=D[D.measure=='gap_change'];lines+=['',f"Projection reduces the absolute gap between mean p and event base rate in {int((x.estimate<0).sum())}/44 groups and increases it in {int((x.estimate>0).sum())}/44 (707 distinct engines). This is a point-estimate classification, not a CI decision. D_mechanism.csv also gives base rates, raw/projected means and both absolute gaps, all with CIs.",'', '## E. Adjusted flag associations','',f"E_associations.csv retains all 264 exploratory outcome/adjustment rows: both outcomes, all 44 groups, RUL adjustment alone, RUL plus cubic raw p and the 20–40 indicator, and RUL-adjusted analysis restricted to the 20–40 band. Each row reports its actual regression engine count, flagged distinct engines, coefficient, CI, own mean, coefficient and CI divided by own mean, approximate MDE and MDE/mean. All point coefficients are identifiable; {int((E.undefined_draws>0).sum())} rows have at least one undefined bootstrap draw (maximum {int(E.undefined_draws.max())}/2000). Those draws are counted, not replaced with zero.",'', 'RUL adjustment uses the earlier cubic capped-RUL convention and fit-specific intercepts. The additional raw-p adjustment uses a cubic and the raw-RUL 20–40 indicator. Own-mean ratios use the same group and, for restricted analyses, the same band. MDE is approximately 2.801585 times bootstrap coefficient SD for 80% power at two-sided alpha .05, conditional on the observed design and fixed fits. It is not an exact power calculation. Associations are noncausal, with no multiplicity correction.','', '## Provenance and limits','',f"Current session records configured model gpt-6.1-sol, runtime 0.166.0-alpha.5.1, and current desktop build 26.1027.3384.0 (OpenAI.Codex_26.1027.3384.0_x64__2p2nqsd0c76g0). Historical app/build and executable identifiers are retained in provenance.json, explicitly separated from current session identity. Exact served checkpoint/build identifier is unavailable. Software: Python {prov['python']}, NumPy {prov['numpy']}, SciPy {prov['scipy']}, scikit-learn {prov['sklearn']}.",'', 'All calibration endpoints are retrospective and can differ in sampling policy from official-test final windows. The same official-test fleets have been examined before; the protocol lock does not make these fresh confirmatory tests. Pooling across original/equal-search/extra models describes this fixed roster rather than independent model replications. Independent human review is still missing.','', 'The HTML companion contains every result in searchable tables. CSVs retain full numeric precision; displayed HTML numbers use six significant digits. Protocol, roster, fit parameters, bin edges, source code, input hashes, correction log and final manifest accompany the results.']
(O/'report.md').write_text('\n'.join(lines),encoding='utf-8')
intro=''.join('<p>'+html.escape(x)+'</p>' for x in lines if x and not x.startswith('#') and not x.startswith('-'))
body='<h1>Exploratory calibration and projection extension</h1>'+intro
for title,df in [('Engine counts',counts),('A: all scores and paired differences',A),('B: all consistency results',B),('B: consistency counts',pd.DataFrame(summary)),('C: fixed distance bins',C),('D: mechanism',D),('E: adjusted flag associations',E)]:body+='<details open><summary>'+title+'</summary><p>Exploratory; engine counts are shown in each row. Search filters rows across tables.</p>'+df.to_html(index=False,float_format=lambda x:f'{x:.6g}',border=0)+'</details>'
(O/'report.html').write_text('<!doctype html><html><meta charset="utf-8"><title>Exploratory projection analysis</title><style>body{font:15px system-ui;margin:28px;color:#172235;background:#fafbfc}p{max-width:1100px;line-height:1.55}details{margin:25px 0;overflow:auto}summary{font-size:21px;font-weight:650;cursor:pointer}table{border-collapse:collapse;font-size:12px}th,td{padding:8px;border-bottom:1px solid #dde3eb;text-align:left;white-space:nowrap}th{background:#eaf0f8;position:sticky;top:0}input{padding:12px;width:450px;position:sticky;top:0;background:white;z-index:2}</style><input placeholder="Filter result rows by group, metric or adjustment" oninput="document.querySelectorAll(\'tbody tr\').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(this.value.toLowerCase()))">'+body+'</html>',encoding='utf-8')
checks['existing_eight_groups_64_scores_reproduced']=True;checks['nonidentifiable_association_point_rows']=int(E.estimate.isna().sum());checks['association_rows_with_undefined_draws']=int((E.undefined_draws>0).sum());(O/'checks.json').write_text(json.dumps(checks,indent=2))
manifest=dict(protocol=checks['protocol'],inputs=json.loads((O/'input_hashes_before.json').read_text()),outputs={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in O.iterdir() if p.is_file() and p.name!='manifest.json'},source_sha256=hashlib.sha256((R/'scripts/analyze_calibrator_extension.py').read_bytes()).hexdigest(),report_source_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),independent_human_review='MISSING');(O/'manifest.json').write_text(json.dumps(manifest,indent=2));print('Report complete')
